create extension if not exists "pgcrypto";
create type user_role as enum ('applicant','reviewer','supervisor','compliance_admin');
create type case_status as enum ('draft','processing','review_required','approved','rejected','escalated','closed');
create type exception_severity as enum ('low','medium','high','critical');
create table if not exists organisations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table if not exists users (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references organisations(id), email text not null, password_hash text not null, display_name text not null, role user_role not null default 'applicant', active boolean not null default true, last_login_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organisation_id,email));
create table if not exists cases (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references organisations(id), case_number text not null, title text not null, document_type text not null, status case_status not null default 'draft', risk exception_severity not null default 'low', confidence numeric(5,2), assigned_to uuid references users(id), version integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(organisation_id,case_number));
create table if not exists documents (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references organisations(id), case_id uuid not null references cases(id), filename text not null, mime_type text not null, checksum text not null, storage_key text not null, malware_status text not null default 'pending', version integer not null default 1, created_at timestamptz not null default now(), unique(organisation_id,checksum,version));
create table if not exists extracted_fields (id uuid primary key default gen_random_uuid(), document_id uuid not null references documents(id), field_name text not null, field_value jsonb not null, confidence numeric(5,2), page_number integer, bounding_region jsonb, model_version text, source_snapshot jsonb, created_at timestamptz not null default now());
create table if not exists exceptions (id uuid primary key default gen_random_uuid(), case_id uuid not null references cases(id), type text not null, severity exception_severity not null, status text not null default 'open', evidence jsonb not null default '{}', created_at timestamptz not null default now(), resolved_at timestamptz);
create table if not exists decisions (id uuid primary key default gen_random_uuid(), case_id uuid not null references cases(id), actor_id uuid not null references users(id), outcome text not null, reason text not null, previous_value jsonb, new_value jsonb, model_version text, created_at timestamptz not null default now());
create table if not exists audit_events (id bigserial primary key, organisation_id uuid references organisations(id), actor_id uuid references users(id), action text not null, entity_type text not null, entity_id text, outcome text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists cases_org_status_idx on cases(organisation_id,status,created_at desc) where deleted_at is null;
create index if not exists documents_case_idx on documents(case_id,created_at desc);
create index if not exists exceptions_case_status_idx on exceptions(case_id,status,severity);
create index if not exists audit_events_org_created_idx on audit_events(organisation_id,created_at desc);
